/**
 * Dev-only fixtures that stand in for a real FedEx open-time read until discovery wires it (step-8 phase 1).
 *
 * These are MADE UP. Nobody here has seen a real VIPS open-time list. The fixture text is generated by the same
 * `samplePaste` the /open-time page already offers as "Try a made-up list", so the live path and the paste path read
 * identical input and therefore produce identical scores and reasons — which is exactly what we need to prove the
 * wiring before any real feed exists.
 */

import { samplePaste } from "@/lib/open-time/sample";
import type { BidPack } from "@/types/bidpack";

/** A fixture open-time list for this pack, for exercising the live feed on fixtures. Not a real VIPS list. */
export function fixtureOpenTimeText(pack: BidPack): string {
  return samplePaste(pack);
}
